  ["2a266cf6a0c2cde6"] = { "Così osate trastullarvi con le creature del Re dei Lich? Ramstein, assicurati di dare agli intrusi un benvenuto come si deve.", "." },
  ["2a2dcafdb269f1df"] = { "Non c'è molto altro da dire. Dalaran fu quasi completamente distrutta da Archimonde, e il bastone andò perduto, presumibilmente frantumato dai meccanismi di sicurezza della barriera.\n\nC'è chi crede che sia stato il bastone la causa della rappresaglia di Archimonde.", "." },
  ["2a384e6987d9518f"] = { "Ecco, {name}. Ora puoi parlare con il capo dei Bloodscalp e il suo santone.", "." },
