  ["2a6e8a9a730a7cf8"] = { "Maledetta neve... Ehi, tu sei {name}, vero? Ho appena ricevuto un messaggio per te.", "." },
  ["2a6f64eca493c568"] = { "TEST - riavvia campo di battaglia.", "." },
  ["2a719c6e92c3e1df"] = { "Ho mentito...", "." },
  ["2a8215e96bdeae7e"] = { "Troppo poco, troppo tardi. La diga ha ceduto. Nel migliore dei casi siamo solo un piccolo intoppo.", "." },
  ["2a886bdf4744b2d3"] = { "Va bene, va bene. Potete andare a giocare, ma restate in città. Niente fughe per andare a dare fastidio a Warg e Khara giù vicino all'acqua.", "." },
  ["2a95db487a06ed80"] = { "Addenta una mela fresca e matura.", "." },
  ["2a95f08cec5f5488"] = { "Un tempo, è vero, appartenevo alla razza umana. Ciò che altrimenti sarebbe un difetto torna a nostro vantaggio, {name}, perché conosco a fondo le debolezze degli umani.", "." },
  ["2a9642fac2007053"] = { "Riporta tutte le statue di questa stanza alla posizione iniziale.", "." },
