  ["2ac661a89812ecda"] = { "Josetta è stata una benedizione per questa città con il suo aiuto alle guardie locali. Se la cerchi per apprendere le vie del sacerdozio, la troverai alla Locanda del Fiero Leone.", "." },
  ["2ac6ea3fd5fe7695"] = { "Ah, sei <un/una> curios<o/a>, eh? Eccellente! Fai bene attenzione, questo potrebbe salvarti la pelle quando le cose si mettono male!", "." },
